import { test, expect } from "@playwright/test";
import AxeBuilder from "@axe-core/playwright";

// Helper: log in as the registered test customer
async function loginAsRegisteredCustomer(page: import("@playwright/test").Page) {
  await page.goto("/#/login");

  // Dismiss cookie consent if present
  const dismissBtn = page.getByRole("button", { name: "dismiss cookie message" });
  await dismissBtn.waitFor({ state: "visible", timeout: 4000 }).catch(() => {});
  if (await dismissBtn.isVisible()) {
    await dismissBtn.click();
  }

  // Dismiss welcome banner if present
  const closeBtn = page.getByRole("button", { name: "Close Welcome Banner" });
  await closeBtn.waitFor({ state: "visible", timeout: 4000 }).catch(() => {});
  if (await closeBtn.isVisible()) {
    await closeBtn.click();
  }

  await page.getByLabel("Email").fill(process.env["AQA_APP_USER"] ?? "");
  await page.locator("input[type='password']").fill(process.env["AQA_APP_PASS"] ?? "");
  await page.getByRole("button", { name: "Login" }).click();

  // Precondition: verify authentication succeeded
  await expect(
    page.getByRole("button", { name: "Show/hide account menu" }),
    "Precondition: login must succeed before test can proceed"
  ).toBeVisible({ timeout: 10000 });
}

test.describe("Customer profile and orders", () => {

  // ---------------------------------------------------------------------------
  // SCRUM-25: Customer changes their password
  // ---------------------------------------------------------------------------

  // @story:SCRUM-25 @ac:1 @design:D6 @type:functional @technique:state-transition
  test("AC-1 Correct current password and matching new password changes password and shows confirmation", async ({ page }) => {
    await test.step("Given I am logged in as a registered customer", async () => {
      await loginAsRegisteredCustomer(page);
    });

    await test.step("When I navigate to the Change Password page", async () => {
      await page.goto("/#/privacy-security/change-password");
    });

    // Dismiss any notification banners that appeared after navigation
    await test.step("Dismiss any notification banners", async () => {
      const closeNotif = page.locator("button.close-notification, button[aria-label='Close']").first();
      await closeNotif.waitFor({ state: "visible", timeout: 3000 }).catch(() => {});
      if (await closeNotif.isVisible()) {
        await closeNotif.click().catch(() => {});
      }
    });

    await test.step("Precondition: Change Password form is visible", async () => {
      await expect(
        page.getByRole("heading", { name: "Change Password" }),
        "Precondition: Change Password page must be visible"
      ).toBeVisible({ timeout: 5000 });
    });

    // Step 1: change password from current to new
    await test.step("And I enter the current password", async () => {
      await page.getByLabel("Field to enter the current password").fill(process.env["AQA_APP_PASS"] ?? "");
    });

    await test.step("And I enter the new password", async () => {
      await page.getByLabel("Field for the new password").fill("NewPass123!");
    });

    await test.step("And I enter the new password again", async () => {
      await page.getByLabel("Field to repeat the new password").fill("NewPass123!");
    });

    await test.step("And I click Change", async () => {
      await page.getByRole("button", { name: "Change" }).click();
    });

    await test.step("Then the page displays password changed confirmation", async () => {
      await expect(
        page.getByText("Password successfully changed"),
        "AC-1: confirmation message must appear after successful password change"
      ).toBeVisible({ timeout: 10000 });
    });

    // Step 2: restore original password so other tests keep working (PO comment requirement)
    await test.step("When I navigate to Change Password again to restore original password", async () => {
      await page.goto("/#/privacy-security/change-password");
    });

    await test.step("And I enter the new password as current", async () => {
      await page.getByLabel("Field to enter the current password").fill("NewPass123!");
    });

    await test.step("And I enter the original password as new", async () => {
      await page.getByLabel("Field for the new password").fill(process.env["AQA_APP_PASS"] ?? "");
    });

    await test.step("And I enter the original password as repeat", async () => {
      await page.getByLabel("Field to repeat the new password").fill(process.env["AQA_APP_PASS"] ?? "");
    });

    await test.step("And I click Change to restore", async () => {
      await page.getByRole("button", { name: "Change" }).click();
    });

    await test.step("Then the page displays password changed confirmation again", async () => {
      await expect(
        page.getByText("Password successfully changed"),
        "AC-1: confirmation message must appear after restoring original password"
      ).toBeVisible({ timeout: 10000 });
    });
  });

  // @story:SCRUM-25 @ac:2 @design:D7 @type:functional @technique:equivalence-partitioning
  test("AC-2 Wrong current password is refused with a message", async ({ page }) => {
    await test.step("Given I am logged in as a registered customer", async () => {
      await loginAsRegisteredCustomer(page);
    });

    await test.step("When I navigate to the Change Password page", async () => {
      await page.goto("/#/privacy-security/change-password");
    });

    await test.step("Precondition: Change Password form is visible", async () => {
      await expect(
        page.getByRole("heading", { name: "Change Password" }),
        "Precondition: Change Password page must be visible"
      ).toBeVisible({ timeout: 5000 });
    });

    await test.step("And I enter a wrong current password", async () => {
      await page.getByLabel("Field to enter the current password").fill("WrongPassword999");
    });

    await test.step("And I enter a valid new password", async () => {
      await page.getByLabel("Field for the new password").fill("NewPass123!");
    });

    await test.step("And I repeat the valid new password", async () => {
      await page.getByLabel("Field to repeat the new password").fill("NewPass123!");
    });

    await test.step("And I click Change", async () => {
      await page.getByRole("button", { name: "Change" }).click();
    });

    await test.step("Then the page displays an error about the wrong password", async () => {
      await expect(
        page.getByText("Current password is not correct"),
        "AC-2: error message must appear when current password is wrong"
      ).toBeVisible({ timeout: 10000 });
    });
  });

  // @story:SCRUM-25 @ac:3 @design:D8 @type:functional @technique:equivalence-partitioning
  test("AC-3 Mismatched new password and repeat is refused", async ({ page }) => {
    await test.step("Given I am logged in as a registered customer", async () => {
      await loginAsRegisteredCustomer(page);
    });

    await test.step("When I navigate to the Change Password page", async () => {
      await page.goto("/#/privacy-security/change-password");
    });

    await test.step("Precondition: Change Password form is visible", async () => {
      await expect(
        page.getByRole("heading", { name: "Change Password" }),
        "Precondition: Change Password page must be visible"
      ).toBeVisible({ timeout: 5000 });
    });

    await test.step("And I enter the current password", async () => {
